using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Xml.Linq;
using GuiaFotos.Core;
using System.Security.Cryptography;
using Microsoft.IdentityModel.JsonWebTokens;
using Microsoft.IdentityModel.Tokens;

var root = Path.Combine(Path.GetTempPath(), "guiafotos-tests-" + Guid.NewGuid().ToString("N")); Directory.CreateDirectory(root);
var tools = ToolPaths.Discover(Environment.GetEnvironmentVariable("GUIAFOTOS_TOOLS_ROOT") ?? root);
var library = new MediaLibrary(tools, Path.Combine(root, "cache")); var actions = new FileActions(Path.Combine(root, "state")); var editor = new PhotoEditor(tools, library, actions);
using var catalog = new Catalog(Path.Combine(root, "catalog.sqlite")); var pass = 0; var fail = 0;
async Task Test(string name, Func<Task> body)
{ try { await body(); pass++; Console.WriteLine("PASS " + name); } catch (Exception error) { fail++; Console.WriteLine("FAIL " + name + ": " + error); } }
void Assert(bool condition, string message) { if (!condition) throw new Exception(message); }
async Task Throws(Func<Task> action) { try { await action(); } catch { return; } throw new Exception("Esperava falha."); }
var photo = Path.Combine(root, "foto coração 日本.jpg");
await Tools.Run(tools.Magick, ["-size", "160x100", "gradient:#203030-#e4a273", photo]);
await Tools.Run(tools.ExifTool, ["-overwrite_original", "-DateTimeOriginal=2025:12:25 14:15:16", "-GPSLatitude=12.5", "-GPSLongitude=20.1", "-XMP:Description=privado", "-IPTC:Keywords=teste", photo]);
var originalHash = await Files.Hash(photo); var imported = await library.Inspect(photo);
Assert(imported.Sha256.Length == 0, "Importação não deve ler arquivo inteiro para SHA256.");
// Integrity-sensitive operation fixtures explicitly capture the current full hash.
var item = imported with { Sha256 = originalHash }; catalog.Add(item);
await Test("AV1 decodifica por software sem aceleração de hardware", async () => {
    var avif = Path.Combine(root, "av1-software.avif");
    await Tools.Run(tools.Magick, ["-size", "48x48", "gradient:red-blue", avif]);
    var pixels = await Tools.Run(tools.Ffmpeg, ["-v", "error", "-hwaccel", "none", "-c:v", "libdav1d", "-i", avif, "-frames:v", "1", "-pix_fmt", "rgb24", "-f", "rawvideo", "pipe:1"]);
    Assert(pixels.Length == 48 * 48 * 3, "AV1 não produziu os pixels esperados por CPU.");
});
await Test("catálogo/miniatura/data Unicode; originais intactos", async () => { Assert(item.Taken.Year == 2025 && item.Taken.Month == 12, "Data EXIF ignorada."); Assert(File.Exists(item.Thumbnail), "Sem thumbnail."); Assert(await Files.Hash(photo) == originalHash, "Importação alterou original."); });
await Test("metadados completos e edição efetiva em cópia", async () => { var edited = await editor.MetadataCopy(photo, Path.Combine(root, "out"), new Dictionary<string, string> { ["XMP:Description"] = "Novo título" }); var metadata = await library.Metadata(edited); Assert(metadata.Any(x => x.Key.EndsWith(":Description") && x.Value.ToString() == "Novo título"), "Edição não persistiu."); Assert(await Files.Hash(photo) == originalHash, "Original editado."); });
await Test("bloqueia tags de caminho e coordenadas fora de faixa", async () => { await Throws(() => editor.MetadataCopy(photo, root, new Dictionary<string, string> { ["FileName"] = "outro.jpg" })); await Throws(() => editor.MetadataCopy(photo, root, new Dictionary<string, string> { ["GPSLatitude"] = "999" })); });
await Test("remoção EXIF preserva pixels e original", async () => { var stripped = await editor.StripExif(photo, Path.Combine(root, "out")); var metadata = await library.Metadata(stripped); Assert(!metadata.Keys.Any(x => x.StartsWith("GPS:") || x.StartsWith("ExifIFD:")), "EXIF permaneceu."); var first = await Tools.Run(tools.Ffmpeg, ["-v", "error", "-i", photo, "-frames:v", "1", "-f", "rawvideo", "-pix_fmt", "rgb24", "pipe:1"]); var second = await Tools.Run(tools.Ffmpeg, ["-v", "error", "-i", stripped, "-frames:v", "1", "-f", "rawvideo", "-pix_fmt", "rgb24", "pipe:1"]); Assert(first.SequenceEqual(second), "Pixels foram reencodados sem necessidade."); Assert(await Files.Hash(photo) == originalHash, "Original modificado."); });
await Test("privacidade remove XMP/IPTC/GPS e auditoria não vaza valores", async () => { var stripped = await editor.StripExif(photo, Path.Combine(root, "out"), true); var metadata = await library.Metadata(stripped); Assert(!metadata.Keys.Any(x => x.StartsWith("XMP") || x.StartsWith("IPTC:") || x.StartsWith("GPS:")), "Metadados pessoais permaneceram."); Assert(!File.ReadAllText(stripped + ".audit.json").Contains("privado"), "Auditoria vazou metadado."); });
await Test("Estou com sorte, restauração, rotação e recorte geram derivadas", async () => { foreach (var operation in new[] { "enhance", "restore", "rotate", "crop" }) { var options = operation == "crop" ? new Dictionary<string, string> { ["geometry"] = "80x50+0+0" } : new Dictionary<string, string> { ["degrees"] = "90" }; var output = await editor.Edit(photo, Path.Combine(root, "out"), operation, options); Assert(File.Exists(output) && File.Exists(output + ".recipe.json"), "Derivada sem proveniência."); } Assert(await Files.Hash(photo) == originalHash, "Edição alterou original."); });
await Test("duplicatas exatas e fotos semelhantes", async () => { var copy = Path.Combine(root, "cópia.jpg"); File.Copy(photo, copy); var identical = await library.Inspect(copy); var recoded = Path.Combine(root, "menor.jpg"); await Tools.Run(tools.Magick, [photo, "-resize", "80x50", "-quality", "70", recoded]); var related = await library.Inspect(recoded); Assert(MediaLibrary.Duplicates([item, identical], false).Count == 1, "Duplicata exata não detectada."); Assert(MediaLibrary.Duplicates([item, related], true).Any(x => x.Type.StartsWith("Fotos semelhantes")), "Semelhança não detectada."); });
await Test("vídeos idênticos e recodificados comparados por 3 quadros", async () => { var video = Path.Combine(root, "video.mp4"); await Tools.Run(tools.Ffmpeg, ["-v", "error", "-y", "-f", "lavfi", "-i", "testsrc=size=160x100:rate=8", "-t", "3", "-pix_fmt", "yuv420p", video]); var second = Path.Combine(root, "video2.mp4"); await Tools.Run(tools.Ffmpeg, ["-v", "error", "-y", "-i", video, "-crf", "30", second]); var firstItem = await library.Inspect(video); var secondItem = await library.Inspect(second); Assert(firstItem.VideoFingerprints.Split(',').Length == 3, "Sem assinatura de vídeo."); Assert(MediaLibrary.Duplicates([firstItem, secondItem], true).Any(x => x.Type.StartsWith("Vídeos semelhantes")), "Vídeo recodificado não reconhecido."); });
await Test("ordenação recente primeiro, tags, rating e álbuns persistentes", () => { var older = item with { Path = photo, Taken = new DateTime(2020, 1, 1), Rating = 5, Tags = "família", Album = "Natal" }; catalog.Add(older); Assert(catalog.All("família").Count == 1 && catalog.All()[0].Rating == 5, "Organização não persistiu."); catalog.Add(item); return Task.CompletedTask; });
await Test("renomeação por data tem preview, colisão e undo", async () => { var copy = Path.Combine(root, "rename.jpg"); File.Copy(photo, copy); var testItem = item with { Path = copy }; var plan = FileActions.PlanNames([testItem]); Assert(plan[0].Destination.Contains("000001_2025-12-25"), "Nome incorreto."); var records = await actions.Rename(plan); Assert(File.Exists(records[0].Destination) && !File.Exists(copy), "Não renomeou."); Assert(File.Exists(await actions.Restore(records[0])), "Undo não funcionou."); });
await Test("falha no lote de renomeação faz rollback e marca journal", async () => { var first = Path.Combine(root, "r1.jpg"); var second = Path.Combine(root, "r2.jpg"); File.Copy(photo, first); File.Copy(photo, second); int moves = 0; actions.FaultInjection = stage => { if (stage == "rename-move" && ++moves == 2) throw new IOException("falha simulada"); }; await Throws(() => actions.Rename(FileActions.PlanNames([item with { Path = first }, item with { Path = second }]))); actions.FaultInjection = null; Assert(File.Exists(first) && File.Exists(second), "Rollback perdeu arquivo."); Assert(actions.History().Any(x => x.State == "rolled-back"), "Journal enganoso."); });
await Test("lixeira recupera hash e falha antes de apagar preserva original", async () => { var copy = Path.Combine(root, "delete.jpg"); File.Copy(photo, copy); actions.FaultInjection = stage => { if (stage == "trash-copy") throw new IOException("falha simulada"); }; await Throws(() => actions.Quarantine(copy)); actions.FaultInjection = null; Assert(File.Exists(copy), "Original perdido na falha."); var operation = await actions.Quarantine(copy); Assert(!File.Exists(copy) && operation.State == "committed", "Lixeira não concluída."); var restored = await actions.Restore(operation); Assert(await Files.Hash(restored) == originalHash, "Recuperação alterou bytes."); });
await Test("recupera intenção após journal/crash e tolera journal corrompido", async () => { var copy = Path.Combine(root, "crash.jpg"); File.Copy(photo, copy); actions.FaultInjection = stage => { if (stage == "trash-journal") throw new IOException("interrupção"); }; await Throws(() => actions.Quarantine(copy)); actions.FaultInjection = null; await actions.Recover(); Assert(actions.History().Any(x => x.Source == copy && x.State == "aborted-original-preserved"), "Intenção não reconciliada."); File.WriteAllText(Path.Combine(root, "state", "journal", "corrupt.json"), "broken"); Assert(actions.History().Count > 0, "Um registro corrompido derrubou histórico."); });
await Test("planos IA são validados integralmente antes de mutar", async () => { var invalid = new AiPlan("Inválido", [new("enhance", [0]), new("rotate", [0], new() { ["degrees"] = "45" })]); var runner = new PlanRunner(catalog, library, editor, actions, root); await Throws(() => runner.Execute(invalid, [item])); Assert(await Files.Hash(photo) == originalHash, "Plano inválido alterou original."); AiAssistant.Validate(new("Ok", [new("rotate", [0], new() { ["degrees"] = "90" })]), 1); await Throws(() => { AiAssistant.Validate(new("Shell", [new("shell", [0])]), 1); return Task.CompletedTask; }); });
await Test("ações encadeadas usam a derivada e não o original", async () => { var runner = new PlanRunner(catalog, library, editor, actions, root) { ExportFolder = Path.Combine(root, "chain") }; var result = await runner.Execute(new("encadear", [new("enhance", [0]), new("strip_exif", [0]), new("tag", [0], new() { ["tags"] = "editada" })]), [item]); Assert(result[0].Name.Contains("enhance_sem-exif") && result[0].Tags == "editada", "Plano usou original nas etapas seguintes."); Assert(await Files.Hash(photo) == originalHash, "Plano alterou original."); });
await using var server = new DavFixture();
using var cloud = new Nextcloud(server.Url, "test", "password", server.Handler, allowLoopbackTest: true);
await Test("WebDAV: upload temporário, checksum, MOVE e download", async () => { var verified = await cloud.Upload(photo, "Fotos/arquivo.jpg"); Assert(verified.Sha256 == originalHash, "Hash enviado incorreto."); var output = Path.Combine(root, "download.jpg"); await cloud.Download("Fotos/arquivo.jpg", output, originalHash); Assert(await Files.Hash(output) == originalHash, "Download corrompido."); Assert(server.Methods.Contains("MOVE") && server.Methods.Contains("MKCOL"), "Não usou WebDAV."); });
await Test("upload não sobrescreve; download com hash inválido não publica", async () => { await Throws(() => cloud.Upload(photo, "Fotos/arquivo.jpg")); var output = Path.Combine(root, "bad-download.jpg"); await Throws(() => cloud.Download("Fotos/arquivo.jpg", output, new string('0', 64))); Assert(!File.Exists(output), "Download inválido publicado."); });
await Test("backup usa hash efetivamente enviado mesmo se local mudar após MOVE", async () => { var copy = Path.Combine(root, "backup-mutation.jpg"); File.Copy(photo, copy); server.AfterMove = () => File.AppendAllText(copy, "changed"); var snapshot = await cloud.Backup([item with { Path = copy }], "Backups"); server.AfterMove = null; var restore = Path.Combine(root, "restored"); await cloud.RestoreBackup(snapshot, restore); Assert(await Files.Hash(Path.Combine(restore, "backup-mutation.jpg")) == originalHash, "Manifest registrou hash local novo."); Assert((await cloud.Backups("Backups")).Count == 1, "Backup completo não listado."); });
await Test("snapshots sem manifest e paths maliciosos são rejeitados", async () => { await cloud.EnsureFolder("Backups/incompleto"); Assert((await cloud.Backups("Backups")).All(x => x.Name != "incompleto"), "Snapshot parcial oferecido como completo."); await Throws(() => { Nextcloud.ValidateManifest(new("1", DateTime.UtcNow, [new("../fora.jpg", "a", originalHash, 1)])); return Task.CompletedTask; }); await Throws(() => cloud.Download("../secrets", Path.Combine(root, "bad"))); });
await Test("respostas 401/503 não são tratadas como sucesso", async () => { server.FailStatus = 401; await Throws(() => cloud.Upload(photo, "unauthorized.jpg")); server.FailStatus = 503; await Throws(() => cloud.List()); server.FailStatus = 0; });
await Test("AI OpenAI e Claude usam endpoints reais e convertem plano válido", async () => { var secrets = new MemorySecrets(); secrets.Set("openai-key", "fixture"); secrets.Set("claude-key", "fixture"); var handler = new AiFixture(); var ai = new AiAssistant(secrets, new OpenAiLogin(secrets, Path.Combine(root, "host")), handler); foreach (var provider in new[] { "OpenAI", "Claude" }) { var result = await ai.Plan(provider, "fixture", "melhore", [item]); Assert(result.Actions[0].Operation == "enhance", "Plano não decodificado."); } Assert(handler.Requests.Any(x => x.EndsWith("/responses")) && handler.Requests.Any(x => x.EndsWith("/messages")), "Endpoint incorreto."); });
await Test("stream ChatGPT suporta SSE multilinha e exige conclusão", async () => { var data = "data: {\n" + "data: \"type\":\"response.output_text.delta\",\n" + "data: \"delta\":\"ok\"}\n\n" + "data: {\"type\":\"response.completed\"}\n\n"; Assert(await AiAssistant.ReadResponsesStream(new MemoryStream(Encoding.UTF8.GetBytes(data))) == "ok", "SSE multilinha falhou."); await Throws(() => AiAssistant.ReadResponsesStream(new MemoryStream(Encoding.UTF8.GetBytes("data: {\"type\":\"response.output_text.delta\",\"delta\":\"partial\"}\n\n")))); });
await Test("OAuth rejeita state inválido antes de trocar código", async () => { var secrets = new MemorySecrets(); var login = new OpenAiLogin(secrets, Path.Combine(root, "oauth-host")); Task? callback = null; await Throws(() => login.SignIn(url => { var parameters = new Uri(url).Query.TrimStart('?').Split('&').ToDictionary(x => x.Split('=')[0], x => Uri.UnescapeDataString(x[(x.IndexOf('=') + 1)..])); Assert(parameters.ContainsKey("code_challenge") && parameters["client_id"] == "dynamic_agent_client", "PKCE ausente."); callback = Task.Run(async () => { using var http = new HttpClient(); using var response = await http.GetAsync(parameters["redirect_uri"] + "?state=invalid&code=test"); Assert(response.StatusCode == HttpStatusCode.BadRequest, "State inválido aceito."); }); })); if (callback != null) await callback; Assert(secrets.Get("openai-oauth") == null, "Credencial inválida persistida."); });
await Test("OAuth não usa sessão sem escopo de inferência", async () => { var secrets = new MemorySecrets(); secrets.Set("openai-oauth", Json.Write(new OAuthSession("fixture", "subject", "token", "refresh", "id", DateTime.UtcNow.AddHours(1), "openid"))); await Throws(() => new OpenAiLogin(secrets, Path.Combine(root, "host-no-scope")).Token()); });
await Test("orientação JPEG normalizada antes de remover EXIF", async () => { var copy = Path.Combine(root, "oriented.jpg"); File.Copy(photo, copy); await Tools.Run(tools.ExifTool, ["-overwrite_original", "-Orientation#=6", copy]); var hash = await Files.Hash(copy); var output = await editor.StripExif(copy, Path.Combine(root, "out")); var metadata = await library.Metadata(output); Assert(metadata.Any(x => x.Key.EndsWith(":ImageWidth") && x.Value.ToString() == "100"), "Orientação removida sem girar pixels."); Assert(await Files.Hash(copy) == hash, "Original orientado modificado."); });
await Test("GIF não é achatado silenciosamente pela edição", async () => { var gif = Path.Combine(root, "animation.gif"); await Tools.Run(tools.Magick, ["-size", "30x30", "xc:red", "xc:blue", "-loop", "0", gif]); var hash = await Files.Hash(gif); await Throws(() => editor.Edit(gif, Path.Combine(root, "out"), "enhance")); Assert(await Files.Hash(gif) == hash, "Animação original alterada."); });
await Test("crash após apagar original é recuperado como lixeira concluída", async () => { var copy = Path.Combine(root, "crash-delete.jpg"); File.Copy(photo, copy); actions.FaultInjection = stage => { if (stage == "trash-delete") throw new IOException("crash"); }; await Throws(() => actions.Quarantine(copy)); actions.FaultInjection = null; await actions.Recover(); var operation = actions.History().Single(x => x.Source == copy && x.Type == "trash"); Assert(operation.State == "committed" && !File.Exists(copy), "Estado de crash após delete incorreto."); Assert(await Files.Hash(await actions.Restore(operation)) == originalHash, "Recuperação pós-crash falhou."); });
await Test("crash no lote de rename faz reconciliação na inicialização", async () => { var copy = Path.Combine(root, "crash-rename.jpg"); File.Copy(photo, copy); var entry = FileActions.PlanNames([item with { Path = copy }])[0]; var id = Guid.NewGuid().ToString("N"); actions.Record("rename", entry.Source, entry.Destination, entry.Sha256, "pending", id); Files.AtomicText(Path.Combine(root, "state", "transactions", id + ".json"), Json.Write(new RenameTransaction(id, [entry], "pending"))); File.Move(entry.Source, entry.Destination); await actions.Recover(); Assert(File.Exists(copy) && !File.Exists(entry.Destination), "Rename interrompido não foi desfeito."); });
if (OperatingSystem.IsWindows()) await Test("DPAPI Windows protege credenciais", () => { var store = new WindowsSecrets(Path.Combine(root, "secrets")); store.Set("api-key", "test-secret"); Assert(store.Get("api-key") == "test-secret", "DPAPI falhou."); Assert(!File.ReadAllText(Path.Combine(root, "secrets", "api-key.secret")).Contains("test-secret"), "Segredo em texto claro."); store.Remove("api-key"); return Task.CompletedTask; });
await Test("vídeo com localização: privacidade remove ou recusa sem publicar", async () => { var video = Path.Combine(root, "private-video.mp4"); await Tools.Run(tools.Ffmpeg, ["-v", "error", "-y", "-f", "lavfi", "-i", "color=c=red:s=160x100:r=4", "-t", "2", "-pix_fmt", "yuv420p", video]); await Tools.Run(tools.ExifTool, ["-overwrite_original", "-Keys:GPSCoordinates=+37.75-122.4/", "-Keys:Author=private-person", "-XMP:Description=private-title", video]); var hash = await Files.Hash(video); var output = await editor.StripExif(video, Path.Combine(root, "out"), true); var metadata = await library.Metadata(output); Assert(!metadata.Keys.Any(x => x.StartsWith("Keys:") || x.StartsWith("XMP") || x.EndsWith(":GPSCoordinates")), "Vídeo manteve localização."); Assert(await Files.Hash(video) == hash, "Vídeo original modificado."); });
await Test("TIFF multipágina não é achatado pelo editor", async () => { var tiff = Path.Combine(root, "multi.tiff"); await Tools.Run(tools.Magick, ["-size", "30x30", "xc:red", "xc:blue", tiff]); var hash = await Files.Hash(tiff); await Throws(() => editor.Edit(tiff, Path.Combine(root, "out"), "enhance")); Assert(await Files.Hash(tiff) == hash, "TIFF alterado."); });
await Test("cópia cancelada não publica arquivo parcial", async () => { using var cancelled = new CancellationTokenSource(); cancelled.Cancel(); var output = Path.Combine(root, "cancelled.jpg"); await Throws(() => FileActions.CopyVerified(photo, output, cancelled.Token)); Assert(!File.Exists(output), "Cópia cancelada publicada."); });
await Test("transação committed com journal pending é reconciliada", async () => { var copy = Path.Combine(root, "committed-rename.jpg"); File.Copy(photo, copy); var entry = FileActions.PlanNames([item with { Path = copy }])[0]; var id = Guid.NewGuid().ToString("N"); actions.Record("rename", entry.Source, entry.Destination, entry.Sha256, "pending", id); Files.AtomicText(Path.Combine(root, "state", "transactions", id + ".json"), Json.Write(new RenameTransaction(id, [entry], "committed"))); File.Move(entry.Source, entry.Destination); await actions.Recover(); Assert(actions.History().Any(x => x.GroupId == id && x.State == "committed"), "Commit não reconciliado."); Assert(actions.Warnings.Count > 0, "Journal corrompido ocultado."); });
await Test("backup corrupto não oculta backup válido; tamanho e prefixo validados", async () => { var invalid = Path.Combine(root, "manifest-bad.json"); File.WriteAllText(invalid, "broken"); await cloud.Upload(invalid, "Backups/corrupt/manifest.json"); var backups = await cloud.Backups("Backups"); Assert(backups.Count == 1 && cloud.Warnings.Count >= 2, "Corrupto ocultou snapshot válido."); await Throws(() => { Nextcloud.ValidateManifest(new("1", DateTime.UtcNow, [new("a.jpg", "OutraPasta/a.jpg", originalHash, 1)]), "Backups/snapshot"); return Task.CompletedTask; }); await Throws(() => cloud.Download("Fotos/arquivo.jpg", Path.Combine(root, "wrong-size.jpg"), originalHash, expectedSize: 1)); });
