        var body = request.RequestUri.Host.Contains("anthropic") ? Json.Write(new { content = new[] { new { type = "text", text = plan } }, stop_reason = "end_turn" }) : Json.Write(new { status = "completed", output = new[] { new { type = "message", content = new[] { new { type = "output_text", text = plan } } } } });
        return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK) { Content = new StringContent(body) }); }
