sealed class JwtFixture : HttpMessageHandler
{
    private readonly RSA rsa = RSA.Create(2048);
    public string Scope { get; set; } = "openid chatgpt.tokens.use.direct";
    public string Issue(string subject, string? nonce)
    { var claims = new Dictionary<string, object> { ["sub"] = subject }; if (nonce != null) claims["nonce"] = nonce; return new JsonWebTokenHandler().CreateToken(new SecurityTokenDescriptor { Issuer = "https://auth.openai.com", Audience = "client", Claims = claims, Expires = DateTime.UtcNow.AddMinutes(5), SigningCredentials = new SigningCredentials(new RsaSecurityKey(rsa) { KeyId = "fixture-key" }, SecurityAlgorithms.RsaSha256) }); }
    protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken token)
    {
        string body;
        if (request.RequestUri!.AbsolutePath.EndsWith("jwks.json")) { var parameters = rsa.ExportParameters(false); body = Json.Write(new { keys = new[] { new { kty = "RSA", use = "sig", kid = "fixture-key", alg = "RS256", n = Base64UrlEncoder.Encode(parameters.Modulus), e = Base64UrlEncoder.Encode(parameters.Exponent) } } }); }
        else body = Json.Write(new { access_token = "new-access", refresh_token = "new-refresh", id_token = Issue("subject", null), scope = Scope, expires_in = 3600 });
        return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK) { Content = new StringContent(body) });
    }
    protected override void Dispose(bool disposing) { if (disposing) rsa.Dispose(); base.Dispose(disposing); }
}
